changeSet.sql:
CREATE TYPE user_role AS ENUM ('OWNER', 'INSTRUCTOR', 'STUDENT');
CREATE TABLE organizations ( id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, logo_url TEXT, timezone VARCHAR(64) NOT NULL DEFAULT 'Europe/Kyiv', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE TABLE users ( id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash TEXT NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(32), avatar_url TEXT, role user_role NOT NULL, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );
CREATE INDEX idx_users_organization_id ON users(organization_id);

changeSet.rollback:
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS organizations;
DROP TYPE IF EXISTS user_role;
